import{_ as p,a0 as s,w as h,s as a,ao as r,I as t,x as n,a1 as o,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"3个开源的Python Shell | LCTT x X-CMD","titleTemplate":false,"description":"3个开源的Python Shell | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3个开源的Python Shell | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3个开源的Python Shell | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150527 3 Open Source Python Shells","title":"3个开源的Python Shell","tag":"201506","desc":""},"relativePath":"201506/20150527 3 Open Source Python Shells.md","filePath":"[post].md"}'),P={name:"201506/20150527 3 Open Source Python Shells.md"};function u(y,l,m,d,T,w){const i=s("Link");return h(),a("div",null,[l[26]||(l[26]=r('<h1 id="_3个开源的python-shell" tabindex="-1">3个开源的Python Shell <a class="header-anchor" href="#_3个开源的python-shell" aria-label="Permalink to “3个开源的Python Shell”">​</a></h1><p>Python是一个高级、通用、结构化且强大的开源编程语言，广泛用于各种编程工作。它拥有一个全动态类型系统和自动内存管理，与Scheme，Ruby，Perl和Tcl的十分相似，避免编译型语言的许多复杂地方和难以理解。Python于1991年由Guido van Rossum创造，然后逐渐成长，流行。</p><p>Python是一个非常实用，而且流行的计算机编程语言。使用一个如Python这样的解释型语言的好处之一就是，可以借助其交互的shell探索式地编程。你可以试着代码，而不必专门写一个脚本。但是Python shell也有一些局限性。基本来说，有许多很漂亮的Python shell可选择，都是在基础shell上扩展的。他们每一个都提供了一个极好的交互性的Python 体验。</p><h3 id="bpython" tabindex="-1">bpython <a class="header-anchor" href="#bpython" aria-label="Permalink to “bpython”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Programming/Screenshot-bpython.png" alt=""></p><p>对于Linux，BSD，OS X和Windows来说，bpython是一个不错的Python解释器的界面。</p><p>其想法是提供给用户所有的内置功能，很像现在的IDE（集成开发环境），但是是在一个简单，轻量级的包里，可以在终端窗口里面运行。</p><p>bpython并不追求创造任何新的或者开创性的东西。相反，它聚集了一些简洁的理念，关注于实用性和操作性。</p><p>功能包括：</p><ul><li>内置的语法高亮 - 使用Pygments排版你敲出的代码，并合理配色</li><li>根据你的行为，显示自动补全的建议</li><li>为任何Python函数列出所期望的参数 - 可以显示你调用的任何函数的参数列表</li><li>“Rewind”功能会调出内存里的最后一行代码并重新执行</li><li>可以将你输入的代码送到pastebin</li><li>可以将你输入的代码保存到一个文件</li><li>自动缩进</li><li>支持Python 3</li></ul><hr>',11)),t("ul",null,[t("li",null,[l[1]||(l[1]=n("网址: ",-1)),o(i,{href:"http://www.bpython-interpreter.org/"},{default:e(()=>[...l[0]||(l[0]=[n("www.bpython-interpreter.org",-1)])]),_:1})]),l[2]||(l[2]=t("li",null,"开发者: Bob Farrell and contributors",-1)),l[3]||(l[3]=t("li",null,"证书: MIT License",-1)),l[4]||(l[4]=t("li",null,"版本号: 0.14.1",-1))]),l[27]||(l[27]=r('<h3 id="ipython" tabindex="-1">IPython <a class="header-anchor" href="#ipython" aria-label="Permalink to “IPython”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Programming/Screenshot-ipython.png" alt=""></p><p>IPython是Python shell的一个交互加强版。她提供了一个丰富的工具集合，帮助你交互式地充分利用Python。</p><p>IPython可以用来取代标准的Python shell，也可以与标准Python科学和数值处理工具配合，用做一个科学计算（如Matlab或者Mathematical）的完整工作环境。她支持动态对象内省，有限的输入/输出提示，一个宏系统，会话日志，会话恢复，访问完整的系统外壳，详尽且彩色的追踪报告，自动圆括号补全，自动引号补全和可嵌入其他Python程序。</p><p>功能包括：</p><ul><li>强大的交互Shell（基于终端或者Qt）</li><li>一个基于浏览器的记事本，支持代码，富文本，数学表达式，内置图表和其他富媒介。</li><li>支持交互式的数据可视化和使用GUI工具箱</li><li>灵活，嵌入式的解释器可以加载进你自己的项目里</li><li>易于使用，高效的并行运算工具</li></ul><hr>',7)),t("ul",null,[t("li",null,[l[6]||(l[6]=n("网址: ",-1)),o(i,{href:"http://ipython.org/"},{default:e(()=>[...l[5]||(l[5]=[n("ipython.org",-1)])]),_:1})]),l[7]||(l[7]=t("li",null,"开发者: The IPython Development Team",-1)),l[8]||(l[8]=t("li",null,"证书: BSD",-1)),l[9]||(l[9]=t("li",null,"版本号: 3.1",-1))]),l[28]||(l[28]=r('<h3 id="dreampie" tabindex="-1">DreamPie <a class="header-anchor" href="#dreampie" aria-label="Permalink to “DreamPie”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Programming/Screenshot-DreamPie.png" alt=""></p><p>DreamPie是一个为可靠性和趣味性设计的Python shell。</p><p>DreamPie可以用于任何Python解释器（Jython，IronPython，PyPy）。</p><p>功能包括：</p><ul><li>一个新式的交互shell：窗口被分成历史区域和代码区域，历史区域可以让你看到之前的命令及其输出，代码区域是里敲代码的地方。这样，你可以编辑任意多的代码，就好像在你最喜欢的编辑器里一样，并且适当时候可以执行它。你也可以从其他地方复制代码，编辑并马上运行它</li><li>“只复制代码”命令可以复制你想要的代码，以便你可以把它存入一个文件。代码已经用四个空格缩进进行格式化</li><li>自动补全属性和文件名字</li><li>自动显示函数参数和文档</li><li>在结果历史中保存你最近的结果，备以后用</li><li>可以自动折叠很长的输出，以便你可以专注于重要的地方</li><li>保存会话的历史记录为一个HTML文件，备以后查询。你可以加载历史文件到DreamPie里，并且快速重复之前的命令。</li><li>自动添加圆括号与可选的引号，当你在函数与方法后按下空格键。例如，键入execfile后按下空格会提示execfile(&quot;fn&quot;)</li><li>支持交互的matplotlib绘图</li><li>支持Python 2.5，Python 2.6，Python 3.1，Jython 2.5，IronPython 2.6和PyPy</li><li>难以置信的快速反应</li></ul><hr>',7)),t("ul",null,[t("li",null,[l[11]||(l[11]=n("网址: ",-1)),o(i,{href:"http://www.dreampie.org/"},{default:e(()=>[...l[10]||(l[10]=[n("www.dreampie.org",-1)])]),_:1})]),l[12]||(l[12]=t("li",null,"开发者: Noam Yorav-Raphael",-1)),l[13]||(l[13]=t("li",null,"证书: GNU GPL v3",-1)),l[14]||(l[14]=t("li",null,"版本号: 1.2.1",-1))]),l[29]||(l[29]=t("hr",null,null,-1)),t("p",null,[l[16]||(l[16]=n("via: ",-1)),o(i,{href:"http://www.linuxlinks.com/article/20150523032756576/PythonShells.html"},{default:e(()=>[...l[15]||(l[15]=[n("http://www.linuxlinks.com/article/20150523032756576/PythonShells.html",-1)])]),_:1})]),t("p",null,[l[19]||(l[19]=n("作者：Frazer Kline 译者：",-1)),o(i,{href:"https://github.com/wi-cuckoo"},{default:e(()=>[...l[17]||(l[17]=[n("wi-cuckoo",-1)])]),_:1}),l[20]||(l[20]=n(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:e(()=>[...l[18]||(l[18]=[n("wxy",-1)])]),_:1})]),t("p",null,[l[23]||(l[23]=n("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...l[21]||(l[21]=[n("LCTT",-1)])]),_:1}),l[24]||(l[24]=n(" 原创翻译，",-1)),o(i,{href:"https://linux.cn/"},{default:e(()=>[...l[22]||(l[22]=[n("Linux中国",-1)])]),_:1}),l[25]||(l[25]=n(" 荣誉推出",-1))]),l[30]||(l[30]=t("hr",null,null,-1))])}const b=p(P,[["render",u]]);export{g as __pageData,b as default};
